            v(121,0) = qcx*v(61,0) + wqx*v(61,1)
            v(141,0) = qcy*v(41,0) + wqy*v(41,1) &
               + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
            v(181,0) = qcz*v(61,0) + wqz*v(61,1) &
               + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
            ! --- level m = 4 ---
